/// Picks the POSIX or Windows path literal at compile
/// time. Local because `bun_paths` does not export a macro form yet.
macro_rules! path_literal {
    ($posix:literal, $win:literal) => {{
        #[cfg(windows)]
        {
            $win
        }
        #[cfg(not(windows))]
        {
            $posix
        }
    }};
}

