                    let notes = core::mem::take(&mut debug.notes).into_boxed_slice();
                    log.add_msg(Msg {
                        kind: bun_ast::Kind::Verbose,
                        data: bun_ast::range_data(
                            None,
                            bun_ast::Range {
                                loc: bun_ast::Loc::EMPTY,
                                ..Default::default()
                            },
