        #[derive(Default, Clone)]
        pub struct ServerComponents {
            pub separate_ssr_graph: bool,
            pub server_runtime_import: Box<[u8]>,
            pub server_register_client_reference: Box<[u8]>,
            pub server_register_server_reference: Box<[u8]>,
